import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/inventory")
public class InventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String warehouse = req.getParameter("warehouse");
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Validate sort direction
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }

        // Build query - warehouse and category use parameterized queries
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT item_id, item_name, quantity, unit_price, ");
        sql.append("warehouse_code, category, last_updated ");
        sql.append("FROM inventory WHERE 1=1 ");

        List<String> params = new ArrayList<>();
        if (warehouse != null && !warehouse.isEmpty()) {
            sql.append("AND warehouse_code = ? ");
            params.add(warehouse);
        }
        if (category != null && !category.isEmpty()) {
            sql.append("AND category = ? ");
            params.add(category);
        }

        // Dynamic ORDER BY - sort column from user input
        if (sortCol != null && !sortCol.isEmpty()) {
            sql.append("ORDER BY ").append(sortCol).append(" ").append(direction);
        } else {
            sql.append("ORDER BY item_id ASC");
        }

        resp.setContentType("application/json");
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            for (int i = 0; i < params.size(); i++) {
                stmt.setString(i + 1, params.get(i));
            }

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("item_id", rs.getInt("item_id"));
                row.put("item_name", rs.getString("item_name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("unit_price", rs.getDouble("unit_price"));
                row.put("warehouse_code", rs.getString("warehouse_code"));
                row.put("category", rs.getString("category"));
                row.put("last_updated", rs.getString("last_updated"));
                results.put(row);
            }
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"Database error\"}");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Bulk update quantities - used by warehouse scanners
        String body = new String(req.getInputStream().readAllBytes());
        JSONArray updates = new JSONArray(body);

        String updateSql = "UPDATE inventory SET quantity = ?, last_updated = NOW() WHERE item_id = ? AND warehouse_code = ?";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(updateSql)) {
            conn.setAutoCommit(false);
            for (int i = 0; i < updates.length(); i++) {
                JSONObject u = updates.getJSONObject(i);
                stmt.setInt(1, u.getInt("quantity"));
                stmt.setInt(2, u.getInt("item_id"));
                stmt.setString(3, u.getString("warehouse_code"));
                stmt.addBatch();
            }
            stmt.executeBatch();
            conn.commit();
            resp.getWriter().write("{\"status\":\"ok\"}");
        } catch (SQLException e) {
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"Update failed\"}");
        }
    }
}
